const jobRow = $input.first().json || {};

const toTitleCase = (str) => {
  const acronyms = new Set(['SQL', 'ETL', 'BI', 'KPI', 'KPIS', 'UAT', 'CRM', 'API', 'AI', 'LLM', 'AWS', 'GCP', 'SOP', 'SLA', 'P&L', 'B2B', 'B2C', 'FP&A', 'HR', 'IT', 'QA', 'UI', 'UX', 'ROI', 'OKR', 'OKRS']);
  const minor = new Set(['and', 'or', 'of', 'in', 'to', 'for', 'with', 'on', 'at', 'by']);
  return String(str || '').replace(/\b([A-Za-z0-9&/+-]+)\b/g, (word, _, offset) => {
    if (word.toLowerCase() === 'n8n') return 'n8n';
    const upper = word.toUpperCase();
    if (acronyms.has(upper)) return upper;
    if (minor.has(word.toLowerCase()) && offset > 0) return word.toLowerCase();
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  });
};

const uniqueSkillsMap = new Map();
for (const item of $('1. Read Master Skills Tab (Once)').all()) {
  const category = toTitleCase(String(item.json['Category'] || 'Core Competencies').trim());
  const skill = toTitleCase(String(item.json['Skill Name'] || '').trim());
  if (skill !== '') {
    uniqueSkillsMap.set(`${category}::${skill}`, { category, skill });
  }
}
const skillsRows = Array.from(uniqueSkillsMap.values());

const uniqueCertsMap = new Map();
for (const item of $('2. Read Master Certifications Tab (Once)').all()) {
  const provider = String(item.json['Provider'] || 'Coursera').trim();
  const name = String(item.json['Name of the Certification'] || '').trim();
  const completionDate = String(item.json['Date/Month of Completion'] || 'Completed').trim();
  if (name !== '') {
    uniqueCertsMap.set(`${provider}::${name}`, { provider, name, completionDate });
  }
}
const certsRows = Array.from(uniqueCertsMap.values());

const rawCompany = String(jobRow['Company'] || '').trim();
const company = rawCompany !== '' ? rawCompany : 'Hiring_Organization';
const cleanCompany = company.replace(/[^a-zA-Z0-9_-]/g, '_').replace(/^_+|_+$/g, '') || 'Company';

const positionTitle = String(jobRow['Position - Title'] || '').trim();
const rawJd = String(jobRow['Position - Description'] || '').trim();
const industry = String(jobRow['Industry'] || '').trim() || 'Technology & Enterprise Operations';
const aboutCompany = String(jobRow['About Company'] || '').trim() || `Organization operating in ${industry}`;
const notesForResume = String(jobRow['Notes for Resume'] || '').trim() || 'None provided';

const isMissingBothTitleAndJd = (positionTitle === '' && rawJd === '');

const effectiveJobDescription = rawJd.length >= 40
  ? rawJd
  : `Target Role: ${positionTitle || 'Data & Business Analyst'} at ${company} (${industry}). About Company: ${aboutCompany}. Notes: ${notesForResume}. (Note: Full JD text was not provided in the sheet; infer the top 5-10 industry-standard skills and responsibilities for a ${positionTitle || 'Data Analyst'} in ${industry}.)`;

const effectivePositionTitle = positionTitle !== ''
  ? positionTitle
  : 'Senior Analyst (Inferred from Job Description)';

const resumeId = jobRow['Resume_id'] && String(jobRow['Resume_id']).trim() !== ''
  ? String(jobRow['Resume_id']).trim()
  : `RES-${jobRow['S. No.'] || Date.now()}`;

return [{
  json: {
    sNo: jobRow['S. No.'],
    resumeId,
    company,
    cleanCompany,
    industry,
    jobId: String(jobRow['Job ID'] || 'N/A').trim(),
    positionTitle: effectivePositionTitle,
    jobDescription: effectiveJobDescription,
    notesForResume,
    aboutCompany,
    isMissingBothTitleAndJd,
    masterSkills: skillsRows,
    masterCertifications: certsRows,
    _activeModel: 'gemini-3.5-flash-lite'
  }
}];

