const FALLBACK_MODELS = [
  'gemini-3.5-flash-lite',
  'gemini-2.5-flash-lite',
  'gemini-2.5-flash',
  'gemini-2.0-flash-lite',
  'gemini-2.0-flash',
  'gemini-1.5-flash',
  'gemma-2-27b-it'
];
const upstream = $('Sanitize Fields & Check Edge Cases').last().json;
const staticData = $getWorkflowStaticData('node');
const rowKey = String(upstream.sNo || upstream.resumeId || 'row');
if (staticData.lastRowKey !== rowKey) {
  staticData.lastRowKey = rowKey;
  staticData.failCount = 0;
}
staticData.failCount = (staticData.failCount || 0) + 1;
if (staticData.failCount > 14) {
  throw new Error(`All 7 fallback AI models overloaded at Step 0 after ${staticData.failCount} switches.`);
}
const nextModel = FALLBACK_MODELS[staticData.failCount % FALLBACK_MODELS.length];
return [{ json: { ...upstream, _activeModel: nextModel, _failoverAttempt: staticData.failCount } }];

const prev = $('Sanitize Fields & Check Edge Cases').last().json;
const title = String(prev.positionTitle || '');
const jd = String(prev.jobDescription || '');
const notes = String(prev.notesForResume || '');
const comp = String(prev.company || 'Organization');
const ind = String(prev.industry || 'Technology & Data Analytics');
const combined = `${title} ${jd} ${ind}`.toLowerCase();

let exactRoleSlug = 'bi_data_analyst';
let closestBaseArchetype = 'bi_data_analyst';

if (/\b(data engineer|analytics engineer|etl|data warehouse|data modelling|data modeling|pipeline|bigquery|postgresql|database)\b/i.test(title) || /\b(etl pipeline|data modeling|warehouse architecture)\b/i.test(jd)) {
  exactRoleSlug = 'data_engineering_modelling';
  closestBaseArchetype = 'data_engineering_modelling';
} else if (/\b(product analyst|product manager|growth analyst|monetization|funnel|experimentation|a\/b test)\b/i.test(combined)) {
  exactRoleSlug = 'product_manager';
  closestBaseArchetype = 'bi_data_analyst';
} else if (/\b(financial analyst|fp&a|finance|risk|credit|treasury|reconciliation|audit|controls)\b/i.test(combined)) {
  exactRoleSlug = 'finance_fpa_analyst';
  closestBaseArchetype = 'bi_data_analyst';
} else if (/\b(operations|strategy|consulting|project leader|process|supply chain|program)\b/i.test(combined)) {
  exactRoleSlug = 'operations_strategy';
  closestBaseArchetype = 'bi_data_analyst';
}

const candidateKeywords = [
  ['SQL', /\bsql\b/i],
  ['Python', /\bpython|pandas|numpy\b/i],
  ['Tableau', /\btableau\b/i],
  ['Power BI', /\bpower\s*bi\b/i],
  ['BigQuery', /\bbigquery|cloud data|snowflake|redshift|databricks\b/i],
  ['Data Modelling', /\bdata\s+model|semantic\s+layer|schema\b/i],
  ['ETL & Data Pipelines', /\betl|pipeline|data\s+integration|ingestion\b/i],
  ['KPI & Executive Reporting', /\bkpi|dashboard|executive\s+reporting|bi\b/i],
  ['A/B Experimentation', /\ba\/b|experiment|hypothesis|statistical\b/i],
  ['Predictive & Cohort Analytics', /\bcohort|retention|churn|forecasting|predictive\b/i],
  ['Root-Cause & Variance Analysis', /\broot-cause|variance|anomaly|diagnostic\b/i],
  ['Data Governance & QA', /\bgovernance|data\s+quality|qa|validation|audit\b/i],
  ['Process Automation', /\bautomation|workflow|efficiency|n8n\b/i],
  ['Stakeholder Collaboration', /\bstakeholder|cross-functional|leadership|partner\b/i]
];

const matchedKeywords = [];
for (const [label, regex] of candidateKeywords) {
  if (regex.test(combined)) matchedKeywords.push(label);
}
if (matchedKeywords.length < 6) {
  for (const [label] of candidateKeywords) {
    if (!matchedKeywords.includes(label)) matchedKeywords.push(label);
    if (matchedKeywords.length >= 8) break;
  }
}
const topKeywords = matchedKeywords.slice(0, 8);

function shouldIncludeMarketingProjects(tStr, jStr, nStr) {
  const t = String(tStr || '').toLowerCase();
  const j = String(jStr || '').toLowerCase();
  const n = String(nStr || '').toLowerCase();
  if (/\b(no marketing project|remove marketing project|without marketing project|don't include marketing|do not include marketing)\b/i.test(n)) {
    return false;
  }
  if (/\b(include marketing project|add marketing project|show marketing project)\b/i.test(n)) {
    return true;
  }
  const isMarketingOrTvcTitle = /\b(marketing\s+manager|brand\s+manager|campaign\s+manager|advertising|tvc|tvc\s+production|ad\s+production|ad\s+film|commercial\s+production|creative\s+director|head\s+of\s+marketing|vp\s+marketing|cmo|growth\s+marketing\s+manager|performance\s+marketing\s+manager|marketing\s+lead|marketing\s+director|marketing\s+specialist|advertising\s+manager)\b/i.test(t);
  const isDataOrTechOrFinanceTitle = /\b(data\s+analyst|business\s+intelligence|bi\s+analyst|bi\s+developer|bi\s+specialist|analytics\s+engineer|data\s+scientist|data\s+engineer|product\s+analyst|financial\s+analyst|fp&a|operations\s+analyst|business\s+analyst|data\s*&\s*services|analytics\s+manager|analytics\s+lead|senior\s+analyst|senior\s+specialist|project\s+leader)\b/i.test(t) && !isMarketingOrTvcTitle;
  if (isDataOrTechOrFinanceTitle) return false;
  const requiresTvcOrAdProduction = /\b(tvc|tvc\s+production|television\s+commercial|ad\s+film|commercial\s+production|advertising\s+agency|advertising\s+campaign\s+production|brand\s+film\s+production)\b/i.test(j);
  return Boolean(isMarketingOrTvcTitle || requiresTvcOrAdProduction);
}

const allowMarketingProjects = shouldIncludeMarketingProjects(title, jd, notes);

const blueprint = {
  exact_role_slug: exactRoleSlug,
  closest_base_archetype: closestBaseArchetype,
  top_hard_skills: topKeywords.slice(0, 5),
  top_domain_and_soft_keywords: topKeywords.slice(5, 8),
  core_company_contribution: `Driving scalable SQL/Python data pipelines, governed BI dashboards, and actionable decision support for ${comp}`,
  custom_role_framing_guide: `Frame Sumanto as a ${title} tailored to ${comp} (${ind})`
};

return [{
  json: {
    ...prev,
    roleCategory: exactRoleSlug,
    closestBaseArchetype,
    customRoleFramingGuide: blueprint.custom_role_framing_guide,
    jdKeywords: topKeywords,
    jdBlueprint: blueprint,
    includeMaerke: true,
    includeMarketingProjects: allowMarketingProjects,
    _activeModel: 'gemini-3.5-flash-lite'
  }
}];

const base = $('Parse 5-10 Keywords & Role Blueprint').last().json;
const pgRow = $input.first()?.json || {};
const ref = pgRow.reference || {};
const rules = Array.isArray(pgRow.learned_rules) ? pgRow.learned_rules : [];

let masterSkillsText = '';
try {
  const skillItems = $('1. Read Master Skills Tab (Once)').all();
  masterSkillsText = skillItems.map(i => Object.values(i.json || {}).join(' ')).join(' ').toLowerCase();
} catch (e) {}
const hasPowerBiInMaster = masterSkillsText.includes('power bi');

const formatRules = (sec) => rules
  .filter(r => r.target_section === sec || r.target_section === 'ALL')
  .map((r, i) => `${i + 1}. [${r.rule_type}] ${r.rule_instruction}`)
  .join('\n');

const title = String(base.positionTitle || 'Senior Data Analyst').trim();
const jd = String(base.jobDescription || '').toLowerCase();
const roleCat = String(base.roleCategory || 'data_analyst');

// ============================================================================
// 1. Build Summary: STRICT 80% Existing Experience (Paraphrased) / 20% JD Glimpse
//    - Always starts with grounded title: "Senior Data & Business Analyst"
//    - Sentence 1 & 2 (~80%): Paraphrase of real Highspring + Concentrix + Maerke experience
//    - Sentence 3 (~20%): Max 2 overlapping competency phrases from JD + Master Skills
// ============================================================================
let sentence2 = `Proven track record of analyzing 1M+ monthly records using <strong>SQL, Python, and Tableau</strong> to cut manual reporting overhead by 40%, automate interactive KPI dashboards, and maintain 95% delivery quality across cross-functional teams.`;

if (roleCat === 'product_manager' || /product|growth|funnel|experiment|retention/i.test(title + ' ' + jd)) {
  sentence2 = `Proven track record of analyzing 1M+ monthly records using <strong>SQL, Python, and Tableau</strong> to uncover conversion bottlenecks, cut manual reporting overhead by 40%, and drive 25%–30% gains in customer acquisition across 15+ launches.`;
} else if (roleCat === 'finance_fpa_analyst' || /financ|fp&a|risk|treasury|payment|commercial|pricing|revenue/i.test(title + ' ' + jd)) {
  sentence2 = `Proven track record of analyzing 1M+ monthly records using <strong>SQL, Python, and Tableau</strong> to automate KPI reporting, cut manual overhead by 40%, and drive 25%–30% commercial and operational growth across regional and enterprise accounts.`;
} else if (roleCat === 'operations_program_manager' || /operations|strategy|consulting|workforce|process|program/i.test(title + ' ' + jd)) {
  sentence2 = `Proven track record of analyzing 1M+ monthly records using <strong>SQL, Python, and Tableau</strong> to cut manual reporting overhead by 40%, close operational execution gaps by 30%, and boost workforce and process productivity across cross-functional teams.`;
}

// Pick 2 overlapping competencies (~20% JD glimpse) grounded in Master Skills
const glimpseCandidates = [
  { phrase: 'data cleaning and transformation', match: /pipeline|etl|warehouse|bigquery|postgres|sql|model|clean|wrangl|transform/i },
  { phrase: 'diagnostic root-cause analysis', match: /root-cause|root cause|diagnostic|variance|trend|anomaly|investigat|problem/i },
  { phrase: 'funnel and cohort segmentation', match: /funnel|cohort|retention|churn|conversion|segment|customer|acquisition/i },
  { phrase: 'automated dashboard reporting', match: /dashboard|tableau|bi |visualiz|scorecard|kpi|report/i },
  { phrase: 'workflow automation and QA governance', match: /automat|governance|quality|qa|sla|process|efficiency|streamlin/i },
  { phrase: 'narrative insight synthesis', match: /stakeholder|executive|storytelling|consulting|strategy|presentation|decision/i }
];
const matchedGlimpses = glimpseCandidates.filter(g => g.match.test(jd)).map(g => g.phrase);
const glimpse1 = matchedGlimpses[0] || 'data cleaning and transformation';
const glimpse2 = matchedGlimpses[1] || (glimpse1 === 'diagnostic root-cause analysis' ? 'narrative insight synthesis' : 'diagnostic root-cause analysis');

const summaryHtml = `<p>Senior Data &amp; Business Analyst combining 5+ years of enterprise data analytics and operations intelligence with a strong foundation in commercial strategy and stakeholder consulting. ${sentence2} Adept at applying <strong>${glimpse1}</strong> and <strong>${glimpse2}</strong> to translate complex datasets into clear executive presentations and actionable business decisions.</p>`;

// ============================================================================
// 2. Build Core Skills (100% from Master Skills tab, reordered by JD relevance)
// ============================================================================
const scoreSkill = (s) => {
  const tokens = s.toLowerCase().split(/[\s/&+-]+/).filter(t => t.length > 2);
  let sc = 0;
  for (const t of tokens) {
    if (jd.includes(t)) sc += 2;
  }
  return sc;
};
const sortSkills = (arr) => [...arr].sort((a, b) => scoreSkill(b) - scoreSkill(a));

const cat1Skills = sortSkills([
  'SQL (PostgreSQL, MySQL, BigQuery)', 'Python (Pandas, NumPy)', 'R',
  'Excel', 'Jupyter Notebooks', 'API/Data Integration', 'Database Management'
]);
const rawCat2 = [
  'Tableau',
  ...(hasPowerBiInMaster ? ['Power BI'] : []),
  'Dashboard/Report Automation', 'Interactive Dashboards',
  'Executive Presentations', 'Narrative Insight Synthesis', 'KPI Scorecard Design'
];
const cat2Skills = sortSkills(rawCat2);
const cat3Skills = sortSkills([
  'Data Cleaning & Wrangling', 'Data Transformation', 'Quality Assurance',
  'Automating Workflows (n8n)', 'Identifying Improvement Opportunities', 'Root-Cause & Variance Analysis'
]);
const cat4Skills = sortSkills([
  'Stakeholder Communication', 'Cross-Functional Teamwork', 'Consulting & Client Engagement',
  'Training & Mentorship', 'Critical Thinking & Problem Solving', 'Business Acumen'
]);

const skillsHtml = `<ul>
  <li><strong>Data Analysis &amp; Database Management:</strong> ${cat1Skills.join(', ')}</li>
  <li><strong>Business Intelligence &amp; Visualization:</strong> ${cat2Skills.join(', ')}</li>
  <li><strong>Data Governance &amp; Process Optimization:</strong> ${cat3Skills.join(', ')}</li>
  <li><strong>Stakeholder Collaboration &amp; Strategy:</strong> ${cat4Skills.join(', ')}</li>
</ul>`;

// ============================================================================
// 3. Build Experience (4 Authentic Roles, Paraphrased to Match Angle, Zero Proprietary JD Nouns)
// ============================================================================
const hsBullet1 = (roleCat === 'product_manager' || /product|growth|funnel/i.test(title))
  ? `<li>Spearheaded end-to-end <strong>funnel and behavioral analytics</strong> across 1M+ monthly records using SQL and Python, uncovering conversion bottlenecks and cutting manual reporting overhead by 40%.</li>`
  : ((roleCat === 'finance_fpa_analyst' || /financ|payment|commercial|revenue/i.test(title))
    ? `<li>Spearheaded end-to-end <strong>data profiling and reconciliation</strong> across 1M+ monthly records using SQL and Python, resolving reporting discrepancies and cutting manual overhead by 40%.</li>`
    : `<li>Spearheaded end-to-end <strong>SQL data modelling</strong> and pipeline optimization across 1M+ monthly records using Python and BigQuery, cutting manual reporting overhead by 40%.</li>`);

const hsBullet2 = `<li>Designed and deployed interactive <strong>Tableau dashboards</strong> and automated KPI reporting suites across 15+ cross-functional launches, accelerating leadership decision cycles.</li>`;

const hsBullet3 = `<li>Conducted deep-dive <strong>root-cause analysis</strong> and customer segmentation across multi-source datasets, partnering with engineering and business teams to maintain 95% delivery quality.</li>`;

const csrRoleBlock = base.includeMarketingProjects ? '' : `
<div class="job-block">
  <div class="job-header"><span class="job-title"><strong>Customer Support Representative, Concentrix Daksh – Gurugram, India</strong></span><span class="job-date"><strong>Jan 2021 – Mar 2022</strong></span></div>
  <ul>
    <li>Resolved escalated consumer inquiries by utilizing <strong>CRM telemetry</strong> and historical performance metrics, accelerating ticket resolution speed by 35% across high-volume queues.</li>
    <li>Analyzed user interaction trends to identify recurring <strong>service bottlenecks</strong>, partnering with operations leads to streamline workflows and boost customer satisfaction.</li>
  </ul>
</div>`;

const experienceHtml = `<div class="job-block">
  <div class="job-header"><span class="job-title"><strong>Sr. Data Analyst, Highspring India – Gurugram, India</strong></span><span class="job-date"><strong>Oct 2025 - Present</strong></span></div>
  <ul>
    ${[hsBullet1, hsBullet2, hsBullet3].join('\n    ')}
  </ul>
</div>
<div class="job-block">
  <div class="job-header"><span class="job-title"><strong>Lead Trainer, Concentrix Daksh – Gurugram, India</strong></span><span class="job-date"><strong>April 2022 – Aug 2025</strong></span></div>
  <ul>
    <li>Built automated <strong>performance analytics</strong> trackers and Excel/SQL competency matrices across 200+ specialists, boosting new-hire quality scores by 84% within two quarters.</li>
    <li>Led <strong>diagnostic gap analysis</strong> on operational SLA and quality telemetry, redesigning process workflows to reduce recurring knowledge and execution gaps by 30%.</li>
    <li>Partnered with global operations stakeholders on <strong>capacity planning</strong> and workflow standardization, driving a 25% increase in team productivity and throughput.</li>
  </ul>
</div>${csrRoleBlock}
<div class="job-block">
  <div class="job-header"><span class="job-title"><strong>Founder | Creative Director, Maerke Stratcomm – New Delhi, India</strong></span><span class="job-date"><strong>June 2010 – July 2020</strong></span></div>
  <ul>
    <li>Directed <strong>commercial analytics</strong>, pricing strategy, and market segmentation for 15+ B2B and retail clients, driving a 30% increase in customer acquisition.</li>
    <li>Implemented <strong>funnel performance tracking</strong> and ROI attribution models across regional distribution channels, expanding HORECA and enterprise account revenue by 25%.</li>
  </ul>
</div>`;

const certificationsHtml = `<div class="cert-row"><span class="cert-name">Coursera - Tableau Business Intelligence Analyst Professional Certificate</span><span class="cert-date">May 2025</span></div>
<div class="cert-row"><span class="cert-name">Coursera - Google Advanced Data Analytics</span><span class="cert-date">In Progress</span></div>
<div class="cert-row"><span class="cert-name">Coursera - Google Project Management</span><span class="cert-date">In Progress</span></div>`;

return [{
  json: {
    ...base,
    hasPowerBiInMaster,
    roleReference: ref,
    allActiveRulesCount: rules.length,
    summaryRules: formatRules('SUMMARY'),
    skillsRules: formatRules('CORE_SKILLS'),
    experienceRules: formatRules('EXPERIENCE'),
    certificationsRules: formatRules('CERTIFICATIONS'),
    summaryHtml,
    skillsHtml,
    experienceHtml,
    certificationsHtml,
    _preTailored: true
  }
}];

