const educationHtml = `<div class="edu-row"><span>University of Delhi, B.Comm(Hons.)</span><span class="edu-date">2013 – 2016</span></div>`;
const hobbiesHtml = `<div class="hobbies-line">Practicing Buddhism &nbsp;|&nbsp; Automating life with n8n &nbsp;|&nbsp; Growing Mushrooms</div>`;

