const refitAttempt = Number(ctx.refitAttempt || 0);

let pdfPageCount = 1;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  const latin = buf.toString('latin1');
  const pageObjMatches = latin.match(/\/Type\s*\/Page\b(?!s)/g) || [];
  const countMatches = [...latin.matchAll(/\/Type\s*\/Pages\b[\s\S]{0,300}?\/Count\s+(\d+)/g)].map(m => Number(m[1]));
  if (pageObjMatches.length > 0) {
    pdfPageCount = pageObjMatches.length;
  } else if (countMatches.length > 0) {
    pdfPageCount = Math.max(...countMatches);
  }
} catch (e) {}

const stripTags = (h) => String(h || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const expHtml = String(ctx.experienceHtml || '');
const skillsHtml = String(ctx.skillsHtml || '');
const summaryHtml = String(ctx.summaryHtml || '');
const certsHtml = String(ctx.certificationsHtml || '');
const mpHtml = String(ctx.marketingProjectsHtml || '');

const blockRegex = /<div\s+class=["']job-block["'][^>]*>[\s\S]*?<\/ul>\s*<\/div>/gi;
const jobBlocks = expHtml.match(blockRegex) || expHtml.split(/<div\s+class=["']job-block["'][^>]*>/i).slice(1);
const jobBlockCount = jobBlocks.length;
const expBullets = [...expHtml.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(m => stripTags(m[1]));
const expBulletCount = expBullets.length;
const avgExpBulletWords = expBulletCount > 0
  ? expBullets.reduce((acc, b) => acc + b.split(/\s+/).length, 0) / expBulletCount
  : 0;
const skillBullets = [...skillsHtml.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(m => stripTags(m[1]));
const avgSkillsPerCat = skillBullets.length > 0
  ? skillBullets.reduce((acc, b) => acc + b.split(',').length, 0) / skillBullets.length
  : 0;

