let estimatedVisualLines = 4.5; // Header + contact line
estimatedVisualLines += 1.6 + Math.ceil(stripTags(summaryHtml).length / charsPerLine);
estimatedVisualLines += 1.6 + skillBullets.reduce((acc, b) => acc + Math.max(1, Math.ceil(b.length / charsPerLine)), 0);
estimatedVisualLines += 1.6 + (jobBlockCount * 1.35) + expBullets.reduce((acc, b) => acc + Math.max(1, Math.ceil(b.length / (charsPerLine - 4))), 0);
const certRowCount = (certsHtml.match(/class=["']cert-row["']/gi) || []).length || 2;
estimatedVisualLines += 1.6 + (certRowCount * 1.15);
const hasMarketingProjects = Boolean(mpHtml && mpHtml.trim().length > 10);
if (hasMarketingProjects) {
  estimatedVisualLines += 4.5;
}
estimatedVisualLines += 3.2; // Education + Hobbies

const hasAmpBug = skillsHtml.includes('&Amp;') || expHtml.includes('&Amp;');

// 1. Overflow check: ONLY trigger condense if actual Gotenberg PDF > 1 page (or > 4 roles / > 10 bullets) or &Amp; bug
const isOverflowing = (pdfPageCount > 1) || (jobBlockCount > 4) || (expBulletCount > 11) || hasAmpBug;

// 2. Underflow (Too Short) check: if 1 page, but < 3 roles OR < 8 bullets OR bullets are overly short (< 16 words avg) OR visual lines < 40
const minTargetBullets = hasMarketingProjects ? 8 : 8;
const isTooShort = (pdfPageCount === 1) && !isOverflowing && (
  jobBlockCount < (hasMarketingProjects ? 3 : 4) ||
  expBulletCount < minTargetBullets ||
  ( !hasMarketingProjects && estimatedVisualLines < 41.0 ) ||
  avgExpBulletWords < 15.5 ||
  avgSkillsPerCat < 5.5
);

let refitMode = 'NONE';
if (isOverflowing) {
  refitMode = 'CONDENSE';
} else if (isTooShort) {
  refitMode = 'EXPAND';
}

const needsRefitLoop = Boolean((refitMode !== 'NONE') && refitAttempt < 3);

return [{
  json: {
    ...ctx,
    pdfPageCount,
    jobBlockCount,
    expBulletCount,
    avgExpBulletWords: Math.round(avgExpBulletWords * 10) / 10,
    avgSkillsPerCat: Math.round(avgSkillsPerCat * 10) / 10,
    estimatedVisualLines: Math.round(estimatedVisualLines * 10) / 10,
    refitMode,
    needsRefitLoop,
    refitAttempt
  },
  binary: item.binary
}];

