const prev = $('Check PDF Page Count (1-Page Inspector)').last().json;
const nextAttempt = Number(prev.refitAttempt || 0) + 1;
const mode = prev.refitMode || 'CONDENSE';

const blockRegex = /<div\s+class=["']job-block["'][^>]*>[\s\S]*?<\/ul>\s*<\/div>/gi;
let blocks = String(prev.experienceHtml || '').match(blockRegex) || [];
let candidateSkillsHtml = String(prev.skillsHtml || '');
let cssOverride = prev.cssOverride || null;

if (mode === 'EXPAND') {
  const hasCsr = blocks.some(b => /Customer\s+Support\s+Representative/i.test(b));
  if (!hasCsr && !prev.marketingProjectsHtml) {
    const csrBlock = `<div class="job-block">
  <div class="job-header"><span class="job-title"><strong>Customer Support Representative, Concentrix Daksh – Gurugram, India</strong></span><span class="job-date"><strong>Jan 2021 – Mar 2022</strong></span></div>
  <ul>
    <li>Resolved escalated consumer inquiries by utilizing <strong>CRM telemetry</strong> and historical performance metrics, accelerating ticket resolution speed by 35% across high-volume queues.</li>
    <li>Analyzed user interaction trends to identify recurring <strong>service bottlenecks</strong>, partnering with operations leads to streamline workflows and boost customer satisfaction.</li>
  </ul>
</div>`;
    if (blocks.length >= 2) {
      blocks.splice(2, 0, csrBlock);
    } else {
      blocks.push(csrBlock);
    }
  }
  const hasMaerke = blocks.some(b => /Maerke\s+Stratcomm/i.test(b));
  if (!hasMaerke) {
    blocks.push(`<div class="job-block">
  <div class="job-header"><span class="job-title"><strong>Founder | Creative Director, Maerke Stratcomm – New Delhi, India</strong></span><span class="job-date"><strong>June 2010 – July 2020</strong></span></div>
  <ul>
    <li>Directed <strong>commercial analytics</strong>, pricing strategy, and market segmentation for 15+ B2B and retail clients, driving a 30% increase in customer acquisition.</li>
    <li>Implemented <strong>funnel performance tracking</strong> and ROI attribution models across regional distribution channels, expanding HORECA and enterprise account revenue by 25%.</li>
  </ul>
</div>`);
  }
} else {
  // CONDENSE mode: Keep all 4 roles intact, tighten CSS first so all 4 roles fit on 1 page!
  const baseCss = $('CSS Style Window (Edit Anytime)').last().json.cssStyles || '';
  cssOverride = baseCss
    .replace('margin: 0.34in 0.40in;', 'margin: 0.28in 0.38in;')
    .replace('font-size: 9.9pt;', nextAttempt === 1 ? 'font-size: 9.55pt;' : 'font-size: 9.3pt;')
    .replace('line-height: 1.32;', nextAttempt === 1 ? 'line-height: 1.26;' : 'line-height: 1.22;')
    .replace('margin-bottom: 5.5px;', 'margin-bottom: 4px;')
    .replace('margin-top: 8px;', 'margin-top: 6px;');

  if (nextAttempt >= 2) {
    const bulletBudgets = [3, 2, 2, 2];
    blocks = blocks.slice(0, 4).map((blk, idx) => {
      const maxB = bulletBudgets[idx] || 2;
      const liMatches = [...blk.matchAll(/<li[^>]*>[\s\S]*?<\/li>/gi)].map(m => m[0]);
      return blk.replace(/<ul>[\s\S]*?<\/ul>/i, `<ul>\n    ${liMatches.slice(0, maxB).join('\n    ')}\n  </ul>`);
    });
  }
}

return [{
  json: {
    ...prev,
    skillsHtml: candidateSkillsHtml,
    experienceHtml: blocks.slice(0, 4).join('\n'),
    cssOverride,
    refitAttempt: nextAttempt,
    _isRefitPass: true
  }
}];

